{
  "summary": "The initial term of the Agreement lasts for three years from the Effective Date of 15 April 2009, and automatically renews annually unless notice of termination is given ninety days prior.",
  "evidence": [
    {
      "passage_id": 4,
      "quote": "This Strategic Alliance Agreement (this \"Agreement\"), effective as of 15 April, 2009 (the \"Effective Date\")"
    },
    {
      "passage_id": 5,
      "quote": "Unless terminated sooner, the term of this Agreement shall begin on the Effective Date and continue for three (3) years thereafter (the \"Initial Term\") and shall automatically renew for additional one (1) year terms on the terms and conditions set forth herein (each a \"Renewal Term\" and collectively, the \"Term\") unless either party gives the other Party Notice of its intention to terminate this Agreement ninety (90) days before the end of the Initial Term or Renewal Term, if any."
    }
  ]
}
